"""Stage the reviewed attendance-compatible language release; never edit live files here."""
from pathlib import Path
import base64, hashlib, json, shutil, subprocess, sys, tempfile, zlib

VARIANTS = json.loads(zlib.decompress(base64.b64decode('')))

def prepare(source, app):
    stage = Path(tempfile.mkdtemp(prefix="rsp-language-compatible-")) / "source"
    shutil.copytree(source, stage)
    script = (stage / "docs/deploy-language-online-classes.sh").read_text()
    for name, versions in VARIANTS.items():
        actual = (app / name).read_bytes()
        text = actual.decode().replace("\r\n", "\n")
        if text in (versions["old"], versions["merged"]):
            (stage / name).write_text(versions["merged"])
            import re
            pattern = r'(test "\$\(sha256sum "\$app/' + re.escape(name) + r'".*? = ")[0-9a-f]{64}(".*)'
            script, count = re.subn(pattern, lambda m: m[1] + hashlib.sha256(actual).hexdigest() + m[2], script)
            assert count == 1, name
            print("Preserved attendance changes:", name, flush=True)
    attendance = app / "online_classes/migrations/0002_bbbattendancehook_bbbattendanceevent.py"
    if attendance.exists():
        name = "online_classes/migrations/0003_merge_language_attendance.py"
        content = 'from django.db import migrations\n\nclass Migration(migrations.Migration):\n    dependencies = [("online_classes", "0002_bbbattendancehook_bbbattendanceevent"), ("online_classes", "0002_onlineclass_is_language")]\n    operations = []\n'
        if (app / name).exists() and (app / name).read_text() != content:
            raise RuntimeError("Unexpected migration: " + name)
        (stage / name).write_text(content)
        script = script.replace("files=(", "files=(\n  " + name, 1)
        print("Prepared attendance/language migration merge", flush=True)
    script = script.replace("set -Eeuo pipefail", "set -Eeuo pipefail\ntrap 'printf \"Deployment stopped at line %s before completion.\\n\" \"$LINENO\" >&2' ERR", 1)
    (stage / "docs/deploy-language-online-classes.sh").write_text(script)
    return stage

if __name__ == "__main__":
    source = Path(sys.argv[1]).resolve()
    stage = prepare(source, Path("/srv/rsp"))
    subprocess.run(["bash", str(stage / "docs/deploy-language-online-classes.sh"), str(stage), sys.argv[2]], check=True)
